            { theme: "Character Traits 📖", themeJpn: "性格の特徴", sub: [{eng: "Reliability", jpn: "信頼性"}, {eng: "Punctuality", jpn: "時間厳守"}, {eng: "Approachability", jpn: "親しみやすさ"}] }
