            { theme: "Cultural Impact 📖", themeJpn: "文化的影響", sub: [{eng: "Shared moments", jpn: "共有される瞬間"}, {eng: "Sparking conversations", jpn: "会話のきっかけ"}, {eng: "Shaping values", jpn: "価値観の形成"}] }
